import{z as d,x as E,o as r,c as A,q as i,j as l,D as t,d as s,s as n,S as p,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"栈与调用","description":"","frontmatter":{"title":"栈与调用","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stack-adt.md","filePath":"cs/stack-adt.md","lastUpdated":1791063341000}'),B={name:"cs/stack-adt.md"};function c(m,a,h,u,f,D){const o=E("Mermaid");return r(),A("div",null,[a[2]||(a[2]=i('<h1 id="栈与调用" tabindex="-1">栈与调用 <a class="header-anchor" href="#栈与调用" aria-label="Permalink to &quot;栈与调用&quot;">​</a></h1><div class="epigraph"><p>只允许在一端插入删除，后进先出就自动对齐过程调用的进入与返回。</p><footer>—— 据 Dijkstra, Recursive Programming, Numerische Mathematik 1960；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/dll-circular">上一课</a>给出序列的两种表示。<a href="/cs/calling-convention-stack">调用约定与栈</a>已经在 ISA 里用连续栈传参、存返回地址。本课不重讲 <code>jal</code>/<code>ret</code> 和帧指针。缺口是把栈写成 ADT：操作只有 push/pop/peek，从而同一合同既能解释硬件调用栈，也能解释后课的括号匹配与 DFS 控制。表示可以是数组顶指针，也可以是链表头。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>通用序列允许在中间改。调用需要的纪律更窄：被调者返回前，调用者的局部必须原样在。缺口不是再讲一遍 RISC-V 栈约定，而是<strong>LIFO 合同</strong>：后压入的先弹出，空栈弹出无定义。有了合同，硬件栈只是一种表示；表达式求值、递归改为迭代，用同一套操作。<span class="marginnote">术语翻译：ADT（抽象数据类型）就是只规定「能做哪些操作、满足什么性质」，不规定内部怎么存——栈的合同只有 push/pop/peek，底下是数组顶指针还是链表头，合同不管。</span></p><p><a href="/cs/asymptotic-notation">渐近记号</a>下，数组表示的 push/pop 是 \\(\\Theta(1)\\) 摊还或最坏（定容则最坏）。链表表示最坏 \\(\\Theta(1)\\) 但局部性差。调用栈选数组，因为帧连续、地址可算。</p><p><span class="marginnote">Dijkstra 用栈把递归从硬件里解放成程序员可推理的结构。本课把 ISA 已有的那一端和 ADT 对齐。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>抽象状态是序列，只暴露尾端。push 把元素接到尾，pop 去掉尾。空与满是前置条件或返回值，本课不规定异常政策。</p>',9)),(r(),l(p,null,{default:t(()=>[n(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUSH%5B%22push%22%5D%20--%3E%20TOP%5B%22%E5%8F%AA%E5%8A%A8%E6%A0%88%E9%A1%B6%22%5D%0A%20%20POP%5B%22pop%22%5D%20--%3E%20TOP%0A%20%20TOP%20--%3E%20LIFO%5B%22%E5%90%8E%E8%BF%9B%E5%85%88%E5%87%BA%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"硬件调用：push 返回地址与溢出寄存器，pop 恢复。递归深度对应栈高。本课不把堆分配的「调用栈溢出检测」写成操作系统课。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[s("LIFO 匹配嵌套寿命：内层帧活着时外层不能先弹。括号、树的后序、函数调用是同一模式。队列下一课改成 FIFO，嵌套寿命对不上，但生产者-消费者对得上。"),e("span",{class:"marginnote"},"直觉类比：LIFO 像叠盘子——最后放上去的最先被拿走；函数调用同理，最内层最先返回，外层帧才轮得到恢复。")],-1)),(r(),l(p,null,{default:t(()=>[n(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22main%20%E8%B0%83%E7%94%A8%20f%22%5D%20--%3E%20F1%5B%22%E5%8E%8B%E5%85%A5%20f%20%E7%9A%84%E5%B8%A7%22%5D%0A%20%20F1%20--%3E%20C2%5B%22f%20%E8%B0%83%E7%94%A8%20g%22%5D%0A%20%20C2%20--%3E%20F2%5B%22%E5%8E%8B%E5%85%A5%20g%20%E7%9A%84%E5%B8%A7%22%5D%0A%20%20F2%20--%3E%20R2%5B%22g%20%E8%BF%94%E5%9B%9E%22%5D%0A%20%20R2%20--%3E%20P2%5B%22%E5%BC%B9%E5%87%BA%20g%20%E5%B8%A7%EF%BC%9Af%20%E7%9A%84%E5%B1%80%E9%83%A8%E5%8E%9F%E6%A0%B7%E5%9C%A8%22%5D%0A%20%20P2%20--%3E%20R1%5B%22f%20%E8%BF%94%E5%9B%9E%22%5D%0A%20%20R1%20--%3E%20P1%5B%22%E5%BC%B9%E5%87%BA%20f%20%E5%B8%A7%EF%BC%9Amain%20%E7%BB%A7%E7%BB%AD%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p>数组定容栈会满：递归过深是合同失败，不是加法溢出。动态数组把满变成摊还扩容，分析在后课。peek 不改状态，只读顶端；空栈上的 peek 与 pop 同一前置条件。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入双端队列，不把栈写成可随机访问的数组——即便表示是数组，合同也不给下标。线程各有调用栈，共享堆，那是操作系统课；此处单线程顺序执行。<span class="marginnote">常见误区：以为栈用数组实现就能按下标访问中间元素。合同不提供这个操作——绕过 push/pop 直接取下标，LIFO 的性质和推理就全部失效了。</span></p><p>后课默认：谈到栈，指 LIFO 操作，常数时间一端更新。缓冲与异步需要另一端进、一端出。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>栈 = 序列合同收窄到 LIFO；与调用帧嵌套同构。</li><li>表示可用数组顶或链表头；调用栈选连续数组。</li><li>FIFO 缓冲是下一课的缺口。</li><li>合同不提供按下标取元素，即使表示恰好是数组。</li><li>出处：Dijkstra, 1960；Cormen et al. 栈；本栏调用约定课。</li></ul>',6))])}const _=d(B,[["render",c]]);export{T as __pageData,_ as default};
